__NUXT_JSONP__("/safety-covid19", (function(a){return {data:[{details:{slug:"en",pageTitle:"MLI keeps everybody safe during the pandemic | Mentor Language Institute",pageDescription:a,title:"MLI keeps everybody safe during the pandemic",subtitle:[a,"MLI is currently accepting both overseas and transfer students."],image:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fsafety-measure.png",steps:{title:"Here are \u003Cb\u003E6 safety measures\u003C\u002Fb\u003E MLI requires of students who attend in-person classes.",lists:[{step:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fstep-1.png",description:["MLI will make vaccinations a requirement for everyone on campus, in order to keep everybody safe. If you are unwilling or unable to get vaccinated, you must take a PCR test and give the test results to MLI front desk staff every Monday."],gallery:[{image:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002FVaccinationproof.png",note:"COVID-19 Vaccination Certificate"}]},{step:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fstep-2.png",description:["Students need to get tested for COVID-19 no more than 3 days before travel by air into the United States (US) and provide MLI negative test results in English. Students must email MLI a copy of the results before departure and bring the original PCR test results to school.","If the student fails to provide MLI with PCR test results, he\u002Fshe must quarantine for 10 days after arrival to the U.S. As long as there are no COVID-19 symptoms, the student is allowed to start his\u002Fher program in-person after the 10-day quarantine."],gallery:[{image:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fsample-pcr-negative-proof.jpg",note:"Sample COVID19 Negative Result"}]},{step:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fstep-3.png",description:["When entering school, everyone must sanitize their hands using the disinfect at entrance and get their temperature checked. Temperature must be under 99.5F (37.5℃)."],gallery:[{image:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fscanning.png"}]},{step:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fstep-4.png",description:["Everyone is required to wear a face mask at all times while at school. Social distancing is maintained; 6-feet distance between students' desks."],icon:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Ficon-mask-orange.png",gallery:[{image:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fclassroom-setup.jpg"}]},{step:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fstep-5.png",description:["Before and after each class, classrooms, common areas and frequently touched surfaces are cleaned and disinfected according to \u003Ca href='https:\u002F\u002Fwww.cdc.gov\u002Fcoronavirus\u002F2019-ncov\u002Fcommunity\u002Fclean-disinfect\u002Findex.html' target='_blank'\u003ECDC\u003C\u002Fa\u003E guidelines."],gallery:[{image:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fcleaning.png"}]},{step:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Fstep-6.png",description:["Plastic protection has been installed at the front desk area."],gallery:[{image:"\u002Fimages\u002Fcovid19\u002Fsafety-measure\u002Ffront-desk.jpg"}]}]},dir:"\u002Fsafety-covid19",path:"\u002Fsafety-covid19\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:30.812Z",updatedAt:"2025-05-26T12:06:27.901Z"}}],fetch:{},mutations:void 0}}("MLI currently offers in-person Conversation classes (Intermediate & Advanced) and online programs including; ESL, TOEFL®︎, IELTS™️, Business English plus TOEIC®︎ and Life Skills English.")));